import type { ProtocolDecoder, PacketMeta, DecodedPacket } from './index.js';
import { OpcUaReader } from './opcua-binary.js';

// ── OPC UA StatusCodes ─────────────────────────────────────────────────────
// Values verified against OPC Foundation Opc.Ua.StatusCodes.csv via
// open62541 (ua_statuscodes.h), python-opcua, and FreeOPCUA, all
// autogenerated from the same OPC Foundation schema.

const STATUS_CODE_NAMES: Record<number, string> = {
	0x00000000: 'Good',
	// General
	0x80010000: 'BadUnexpectedError',
	0x80020000: 'BadInternalError',
	0x80030000: 'BadOutOfMemory',
	0x80040000: 'BadResourceUnavailable',
	0x80050000: 'BadCommunicationError',
	0x80060000: 'BadEncodingError',
	0x80070000: 'BadDecodingError',
	0x80080000: 'BadEncodingLimitsExceeded',
	0x800A0000: 'BadTimeout',
	0x800B0000: 'BadServiceUnsupported',
	0x800F0000: 'BadNothingToDo',
	0x80100000: 'BadTooManyOperations',
	// Security / certificates
	0x80120000: 'BadCertificateInvalid',
	0x80130000: 'BadSecurityChecksFailed',
	0x80140000: 'BadCertificateTimeInvalid',
	0x80150000: 'BadCertificateIssuerTimeInvalid',
	0x80160000: 'BadCertificateHostNameInvalid',
	0x80170000: 'BadCertificateUriInvalid',
	0x80180000: 'BadCertificateUseNotAllowed',
	0x80190000: 'BadCertificateIssuerUseNotAllowed',
	0x801A0000: 'BadCertificateUntrusted',
	0x801B0000: 'BadCertificateRevocationUnknown',
	0x801C0000: 'BadCertificateIssuerRevocationUnknown',
	0x801D0000: 'BadCertificateRevoked',
	0x801E0000: 'BadCertificateIssuerRevoked',
	// Secure channel / session
	0x80220000: 'BadSecureChannelIdInvalid',
	0x802A0000: 'BadRequestHeaderInvalid',
	0x80540000: 'BadSecurityModeRejected',
	0x80550000: 'BadSecurityPolicyRejected',
	0x80560000: 'BadTooManySessions',
	// TCP transport (OPC 10000-6 §7.1.2.5)
	0x807D0000: 'BadTcpServerTooBusy',
	0x807E0000: 'BadTcpMessageTypeInvalid',
	0x807F0000: 'BadTcpSecureChannelUnknown',
	0x80800000: 'BadTcpMessageTooLarge',
	0x80810000: 'BadTcpNotEnoughResources',
	0x80820000: 'BadTcpInternalError',
	0x80830000: 'BadTcpEndpointUrlInvalid',
	0x80850000: 'BadRequestTimeout',
	0x80BE0000: 'BadProtocolVersionUnsupported',
};

function statusCodeName(code: number): string {
	return STATUS_CODE_NAMES[code] ?? `0x${(code >>> 0).toString(16).padStart(8, '0')}`;
}

// ── Message and chunk type sets ────────────────────────────────────────────

const MESSAGE_TYPE_NAMES: Record<string, string> = {
	HEL: 'Hello',
	ACK: 'Acknowledge',
	ERR: 'Error',
	RHE: 'ReverseHello',
	OPN: 'OpenSecureChannel',
	MSG: 'Message',
	CLO: 'CloseSecureChannel',
};

// Connection-level messages: byte 3 is always 'F' per OPC 10000-6 §7.1.
const CONNECTION_MSG_TYPES = new Set(['HEL', 'ACK', 'ERR', 'RHE']);

// OPN and CLO are always single-chunk ('F') per OPC 10000-6 §6.7.2.
// Only MSG supports intermediate ('C') and abort ('A') chunks.
const ALLOWED_CHUNKS: Record<string, Set<string>> = {
	OPN: new Set(['F']),
	MSG: new Set(['F', 'C', 'A']),
	CLO: new Set(['F']),
};

// Minimum message sizes (header + required body fields)
const MIN_MESSAGE_SIZES: Record<string, number> = {
	HEL: 32,   // 8 header + 5×4 uint32 + 4 string-length prefix
	ACK: 28,   // 8 header + 5×4 uint32
	ERR: 16,   // 8 header + 4 statusCode + 4 string-length prefix
	RHE: 16,   // 8 header + 4+4 two string-length prefixes
	OPN: 16,   // 8 header + 4 secureChannelId + 4 securityPolicyUri prefix
	MSG: 16,   // 8 header + 4 secureChannelId + 4 tokenId
	CLO: 16,   // 8 header + 4 secureChannelId + 4 tokenId
};

// ── Configurable limits ────────────────────────────────────────────────────

export interface OpcuaDecoderConfig {
	maxMessageSize?: number;
	maxStringLength?: number;
}

const DEFAULT_MAX_MESSAGE_SIZE = 16 * 1024 * 1024; // 16 MB
const DEFAULT_MAX_STRING_LENGTH = 4096;
const ABS_MIN_MESSAGE_SIZE = 8; // can't be smaller than header

// ── Decoder ────────────────────────────────────────────────────────────────

export class OpcuaDecoder implements ProtocolDecoder {
	readonly protocols = ['OPC-UA'];

	private maxMessageSize: number;
	private maxStringLength: number;

	constructor(config?: OpcuaDecoderConfig) {
		const rawMax = config?.maxMessageSize ?? DEFAULT_MAX_MESSAGE_SIZE;
		const rawStr = config?.maxStringLength ?? DEFAULT_MAX_STRING_LENGTH;
		this.maxMessageSize = Number.isFinite(rawMax) && rawMax >= ABS_MIN_MESSAGE_SIZE
			? rawMax : DEFAULT_MAX_MESSAGE_SIZE;
		this.maxStringLength = Number.isFinite(rawStr) && rawStr >= 0
			? rawStr : DEFAULT_MAX_STRING_LENGTH;
	}

	decode(payload: Buffer, _meta: PacketMeta): DecodedPacket | null {
		if (payload.length < 8) return null;

		const msgType = payload.toString('ascii', 0, 3);
		if (!MESSAGE_TYPE_NAMES[msgType]) return null;

		const byte3 = String.fromCharCode(payload[3]);
		const messageSize = payload.readUInt32LE(4);

		// Structural validation: message size sanity
		const minSize = MIN_MESSAGE_SIZES[msgType] ?? 8;
		if (messageSize < minSize) {
			return this.malformed(msgType, `messageSize ${messageSize} below minimum ${minSize} for ${msgType}`);
		}
		if (messageSize > this.maxMessageSize) {
			return this.malformed(msgType, `messageSize ${messageSize} exceeds limit ${this.maxMessageSize}`);
		}

		const isConnection = CONNECTION_MSG_TYPES.has(msgType);

		// Connection messages: byte 3 must be 'F'
		if (isConnection && byte3 !== 'F') {
			return this.malformed(msgType, `invalid byte3 '${byte3}' for ${msgType} (expected 'F')`);
		}

		// Secure-conversation messages: validate chunk type
		let chunkType: string | undefined;
		if (!isConnection) {
			const allowed = ALLOWED_CHUNKS[msgType];
			if (!allowed?.has(byte3)) {
				return this.malformed(msgType, `invalid chunk type '${byte3}' for ${msgType}`);
			}
			chunkType = byte3;
		}

		// Distinguish incomplete TCP data from complete-but-truncated messages.
		// If we have fewer bytes than messageSize, this TCP segment doesn't
		// contain the full OPC UA message.
		const availableBytes = Math.min(payload.length, messageSize);
		const incompleteTransport = payload.length < messageSize;

		const baseDetails: Record<string, string | number | boolean> = {
			messageType: msgType,
			messageTypeName: MESSAGE_TYPE_NAMES[msgType],
			messageSize,
		};
		if (chunkType) {
			baseDetails.chunkType = chunkType;
		}
		if (incompleteTransport) {
			baseDetails.incompleteTransport = true;
			baseDetails.availableBytes = payload.length;
		}

		// Coalesced detection: payload contains more bytes than this message
		if (payload.length > messageSize) {
			baseDetails.additionalBytes = payload.length - messageSize;
			if (payload.length >= messageSize + 8) {
				const nextType = payload.toString('ascii', messageSize, messageSize + 3);
				if (MESSAGE_TYPE_NAMES[nextType]) {
					baseDetails.coalescedMessages = true;
				}
			}
		}

		// Abort chunks (MSG only per spec)
		if (chunkType === 'A') {
			return this.decodeAbort(msgType, payload, availableBytes, baseDetails);
		}

		// Bound all readers to messageSize so coalesced data isn't read
		switch (msgType) {
			case 'HEL': return this.decodeHello(payload, availableBytes, baseDetails, incompleteTransport);
			case 'ACK': return this.decodeAck(payload, availableBytes, baseDetails, incompleteTransport);
			case 'ERR': return this.decodeError(payload, availableBytes, baseDetails, incompleteTransport);
			case 'RHE': return this.decodeReverseHello(payload, availableBytes, baseDetails, incompleteTransport);
			case 'OPN': return this.decodeOpenSecureChannel(payload, availableBytes, baseDetails, incompleteTransport);
			case 'MSG': return this.decodeMessage(payload, availableBytes, baseDetails, incompleteTransport);
			case 'CLO': return this.decodeMessage(payload, availableBytes, baseDetails, incompleteTransport);
			default: return null;
		}
	}

	// ── Connection messages ────────────────────────────────────────────────

	private decodeHello(
		buf: Buffer,
		bound: number,
		details: Record<string, string | number | boolean>,
		incomplete: boolean,
	): DecodedPacket {
		const r = new OpcUaReader(buf, 8, bound - 8);

		const protocolVersion = r.readUInt32LE();
		const receiveBufferSize = r.readUInt32LE();
		const sendBufferSize = r.readUInt32LE();
		const maxMessageSize = r.readUInt32LE();
		const maxChunkCount = r.readUInt32LE();

		if (protocolVersion !== null) details.protocolVersion = protocolVersion;
		if (receiveBufferSize !== null) details.receiveBufferSize = receiveBufferSize;
		if (sendBufferSize !== null) details.sendBufferSize = sendBufferSize;
		if (maxMessageSize !== null) details.maxMessageSize = maxMessageSize;
		if (maxChunkCount !== null) details.maxChunkCount = maxChunkCount;

		const endpointUrl = r.readString(this.maxStringLength);
		if (endpointUrl !== undefined && endpointUrl !== null) {
			details.endpointUrl = endpointUrl;
		} else if (endpointUrl === undefined && !incomplete) {
			details.malformedField = 'endpointUrl';
		}

		const urlPart = typeof details.endpointUrl === 'string'
			? ` endpoint=${details.endpointUrl}`
			: '';
		const suffix = incomplete ? ' [incomplete]' : '';
		return {
			operation: 'HEL',
			summary: `HEL Hello${urlPart}${suffix}`,
			status: incomplete ? 'warning' : 'ok',
			details,
		};
	}

	private decodeAck(
		buf: Buffer,
		bound: number,
		details: Record<string, string | number | boolean>,
		incomplete: boolean,
	): DecodedPacket {
		const r = new OpcUaReader(buf, 8, bound - 8);

		const protocolVersion = r.readUInt32LE();
		const receiveBufferSize = r.readUInt32LE();
		const sendBufferSize = r.readUInt32LE();
		const maxMessageSize = r.readUInt32LE();
		const maxChunkCount = r.readUInt32LE();

		if (protocolVersion !== null) details.protocolVersion = protocolVersion;
		if (receiveBufferSize !== null) details.receiveBufferSize = receiveBufferSize;
		if (sendBufferSize !== null) details.sendBufferSize = sendBufferSize;
		if (maxMessageSize !== null) details.maxMessageSize = maxMessageSize;
		if (maxChunkCount !== null) details.maxChunkCount = maxChunkCount;

		const recvStr = receiveBufferSize !== null ? ` recvBuf=${receiveBufferSize}` : '';
		const sendStr = sendBufferSize !== null ? ` sendBuf=${sendBufferSize}` : '';
		const suffix = incomplete ? ' [incomplete]' : '';
		return {
			operation: 'ACK',
			summary: `ACK Acknowledge${recvStr}${sendStr}${suffix}`,
			status: incomplete ? 'warning' : 'ok',
			details,
		};
	}

	private decodeError(
		buf: Buffer,
		bound: number,
		details: Record<string, string | number | boolean>,
		incomplete: boolean,
	): DecodedPacket {
		const r = new OpcUaReader(buf, 8, bound - 8);

		const statusCode = r.readUInt32LE();
		if (statusCode !== null) {
			details.statusCode = statusCode;
			details.statusName = statusCodeName(statusCode);
		}

		const reason = r.readString(this.maxStringLength);
		if (reason !== undefined && reason !== null) {
			details.reason = reason;
		} else if (reason === undefined && statusCode !== null && !incomplete) {
			details.malformedField = 'reason';
		}

		const statusStr = details.statusName ?? (statusCode !== null ? `0x${statusCode.toString(16)}` : 'unknown');
		const reasonStr = typeof details.reason === 'string' ? ` "${details.reason}"` : '';
		const suffix = incomplete ? ' [incomplete]' : '';
		return {
			operation: 'ERR',
			summary: `ERR ${statusStr}${reasonStr}${suffix}`,
			status: 'error',
			details,
		};
	}

	private decodeReverseHello(
		buf: Buffer,
		bound: number,
		details: Record<string, string | number | boolean>,
		incomplete: boolean,
	): DecodedPacket {
		const r = new OpcUaReader(buf, 8, bound - 8);

		const serverUri = r.readString(this.maxStringLength);
		if (serverUri !== undefined && serverUri !== null) {
			details.serverUri = serverUri;
		} else if (serverUri === undefined && !incomplete) {
			details.malformedField = 'serverUri';
		}

		const endpointUrl = r.readString(this.maxStringLength);
		if (endpointUrl !== undefined && endpointUrl !== null) {
			details.endpointUrl = endpointUrl;
		} else if (endpointUrl === undefined && serverUri !== undefined && !incomplete) {
			details.malformedField = 'endpointUrl';
		}

		const urlPart = typeof details.endpointUrl === 'string'
			? ` endpoint=${details.endpointUrl}`
			: '';
		const suffix = incomplete ? ' [incomplete]' : '';
		return {
			operation: 'RHE',
			summary: `RHE ReverseHello${urlPart}${suffix}`,
			status: incomplete ? 'warning' : 'ok',
			details,
		};
	}

	// ── Secure conversation messages ───────────────────────────────────────

	private decodeOpenSecureChannel(
		buf: Buffer,
		bound: number,
		details: Record<string, string | number | boolean>,
		incomplete: boolean,
	): DecodedPacket {
		const r = new OpcUaReader(buf, 8, bound - 8);

		const secureChannelId = r.readUInt32LE();
		if (secureChannelId !== null) details.secureChannelId = secureChannelId;

		// Asymmetric security header (plaintext per OPC 10000-6 §6.7.2.3)
		const securityPolicyUri = r.readString(this.maxStringLength);
		if (securityPolicyUri !== undefined && securityPolicyUri !== null) {
			details.securityPolicy = securityPolicyUri;
		}

		// Sender certificate — skip content, record length
		const senderCertLen = r.skipByteString();
		if (senderCertLen !== undefined && senderCertLen !== null) {
			details.senderCertificateLength = senderCertLen;
		}

		// Receiver certificate thumbprint — skip content, record length
		const thumbprintLen = r.skipByteString();
		if (thumbprintLen !== undefined && thumbprintLen !== null) {
			details.receiverThumbprintLength = thumbprintLen;
		}

		// OPN body after asymmetric security header is always encrypted with
		// the receiver's public key when SecurityPolicy is not None
		// (OPC 10000-6 §6.7.2.3). For None, there is no encryption.
		if (typeof details.securityPolicy === 'string') {
			if (details.securityPolicy.endsWith('#None')) {
				details.bodyVisibility = 'plaintext';
			} else {
				details.bodyVisibility = 'encrypted';
			}
		} else {
			details.bodyVisibility = 'unknown';
		}

		const policyPart = typeof details.securityPolicy === 'string'
			? ` policy=${details.securityPolicy}`
			: '';
		const channelPart = secureChannelId !== null ? ` channel=${secureChannelId}` : '';
		const suffix = incomplete ? ' [incomplete]' : '';
		return {
			operation: 'OPN',
			summary: `OPN OpenSecureChannel${channelPart}${policyPart}${suffix}`,
			status: incomplete ? 'warning' : 'ok',
			details,
		};
	}

	private decodeMessage(
		buf: Buffer,
		bound: number,
		details: Record<string, string | number | boolean>,
		incomplete: boolean,
	): DecodedPacket {
		const msgType = details.messageType as string;
		const chunkType = details.chunkType as string | undefined;
		const r = new OpcUaReader(buf, 8, bound - 8);

		const secureChannelId = r.readUInt32LE();
		if (secureChannelId !== null) details.secureChannelId = secureChannelId;

		// Symmetric security header: tokenId (OPC 10000-6 §6.7.2.4)
		const tokenId = r.readUInt32LE();
		if (tokenId !== null) details.tokenId = tokenId;

		// Without tracking the OPN exchange for this channel, we cannot
		// determine the MessageSecurityMode. The body could be plaintext
		// (None), signed but readable (Sign), or encrypted (SignAndEncrypt).
		details.bodyVisibility = 'unknown';

		const typeName = msgType === 'CLO' ? 'CloseSecureChannel' : 'Message';
		const chunkStr = chunkType === 'C' ? ' intermediate' : '';
		const channelPart = secureChannelId !== null ? ` channel=${secureChannelId}` : '';
		const tokenPart = tokenId !== null ? ` token=${tokenId}` : '';
		const suffix = incomplete ? ' [incomplete]' : '';
		return {
			operation: msgType,
			summary: `${msgType} ${typeName}${chunkStr}${channelPart}${tokenPart}${suffix}`,
			status: incomplete ? 'warning' : 'ok',
			details,
		};
	}

	// ── Abort ──────────────────────────────────────────────────────────────

	private decodeAbort(
		msgType: string,
		buf: Buffer,
		bound: number,
		details: Record<string, string | number | boolean>,
	): DecodedPacket {
		// Abort chunk layout (OPC 10000-6 §6.7.3):
		// Header(8) + SecureChannelId(4) + TokenId(4) +
		// [SequenceNumber(4) + RequestId(4)] + StatusCode(4) + Reason(string)
		//
		// The SequenceHeader and abort body (StatusCode + Reason) are inside the
		// encrypted region when security is active. Without session keys, we
		// can only reliably read SecureChannelId and TokenId.
		const r = new OpcUaReader(buf, 8, bound - 8);

		const secureChannelId = r.readUInt32LE();
		if (secureChannelId !== null) details.secureChannelId = secureChannelId;

		const tokenId = r.readUInt32LE();
		if (tokenId !== null) details.tokenId = tokenId;

		// Attempt to read abort body assuming plaintext (SecurityPolicy#None).
		// Layout after symmetric header: SequenceNumber(4) + RequestId(4) +
		// StatusCode(4) + Reason(string).
		// If these reads produce a recognized StatusCode, report it; otherwise
		// the abort body is likely encrypted.
		const seqNum = r.readUInt32LE();
		const reqId = r.readUInt32LE();
		const statusCode = r.readUInt32LE();

		if (statusCode !== null) {
			const name = STATUS_CODE_NAMES[statusCode];
			if (name || statusCode === 0) {
				// Plausible plaintext abort
				if (seqNum !== null) details.sequenceNumber = seqNum;
				if (reqId !== null) details.requestId = reqId;
				details.abortStatusCode = statusCode;
				details.abortStatusName = statusCodeName(statusCode);

				const reason = r.readString(this.maxStringLength);
				if (reason !== undefined && reason !== null) {
					details.abortReason = reason;
				}
				details.bodyVisibility = 'plaintext';
			} else {
				// StatusCode not recognized — likely encrypted body
				details.bodyVisibility = 'unknown';
			}
		} else {
			details.bodyVisibility = 'unknown';
		}

		const statusStr = typeof details.abortStatusName === 'string'
			? details.abortStatusName as string
			: 'unknown';
		const channelPart = secureChannelId !== null ? ` channel=${secureChannelId}` : '';
		return {
			operation: msgType,
			summary: `${msgType} Abort${channelPart} ${statusStr}`,
			status: 'error',
			details,
		};
	}

	// ── Helpers ─────────────────────────────────────────────────────────────

	private malformed(msgType: string, reason: string): DecodedPacket {
		return {
			operation: msgType,
			summary: `${msgType} malformed: ${reason}`,
			status: 'error',
			details: {
				messageType: msgType,
				malformed: true,
				malformedReason: reason,
			},
		};
	}
}
